// Screen refinements use the existing browser-local booking and conversation models.
state.staffId='alex';
paths.cut=paths.scissors;
for(const list of Object.values(extras.portfolios))for(const item of list)if(item.demo)item.caption=(item.caption||'').replace(/ · demo/g,'');
const shopThread=threadFor('John B.',null,'general');
if(!shopThread.messages.length)shopThread.messages=[{role:'Owner HQ',name:'HAIRFLIX',body:'Hi! How can we help you today?',at:Date.now()-180000,readBy:['Owner HQ']},{role:'Customer',name:'John B.',body:'Hi, is Lara in today?',at:Date.now()-120000,readBy:['Customer']},{role:'Owner HQ',name:'HAIRFLIX',body:'Yes, Lara is in! You can see her next opening under Book, or tell us what time works for you.',at:Date.now()-60000,readBy:['Owner HQ']}];
const shopLogo=()=>'<img class="avatar shop-avatar" src="../assets/logo.webp" alt="HAIRFLIX shop">';

const preferredOpenings={alex:{date:today,time:'3:00 PM'},jordan:{date:today,time:'6:00 PM'},watkins:{date:days[0],time:'11:00 AM'}};
const standardOpeningLabel=openingLabel;
openingLabel=function(id){const slot=preferredOpenings[id];return slot&&HFAppRules.appointmentAt(slot)>Date.now()&&!conflict(id,slot.date,minutes(slot.time),servicesFor(id)[0]?.min||30)?`${slot.date===today?'Today':'Tomorrow'} at ${slot.time}`:standardOpeningLabel(id);};
const priorSampleBusy=sampleBusy;sampleBusy=function(t,len){const slot=preferredOpenings[state.barber];if(slot&&slot.date===state.date&&slot.time===t)return conflict(state.barber,state.date,minutes(t),len);return priorSampleBusy(t,len);};
function addDays(date,n){const d=dateObj(date);d.setDate(d.getDate()+n);return iso(d);}
function dayBlocked(date,barber=state.barber){return extras.blocks.some(b=>b.barber===barber&&b.date===date&&b.start==='00:00'&&b.end==='23:59');}
// Illustrative days off are saved once and never replace recorded appointments.
if(!extras.fiveDayBlocks){for(const id of barbers.map(b=>b.id))for(const n of [2,4,6]){const date=addDays(today,n);if(!bookings.some(b=>b.barber===id&&b.date===date&&b.status!=='cancelled'))extras.blocks.push({id:'day-off-'+id+'-'+date,barber:id,date,start:'00:00',end:'23:59',reason:'Day off'});}extras.fiveDayBlocks=true;save();}
function fiveDates(start,selected,kind){return `<div class="five-date-nav"><button class="icon-btn" data-polish="date-back" data-kind="${kind}" aria-label="Previous five days" ${start<=today?'disabled':''}>${icon('back')}</button><div class="five-dates">${Array.from({length:5},(_,i)=>{const date=addDays(start,i),blocked=dayBlocked(date,kind==='booking'?state.barber:activeBarberId());return `<button class="date ${selected===date?'selected':''}" data-polish="pick-date" data-kind="${kind}" data-date="${date}" ${blocked?'disabled title="Day off"':''}><span>${pretty(date,{weekday:'short'})}</span><strong>${dateObj(date).getDate()}</strong><small>${blocked?'Off':pretty(date,{month:'short'})}</small></button>`;}).join('')}</div><button class="icon-btn" data-polish="date-next" data-kind="${kind}" aria-label="Next five days">${icon('chevron')}</button></div>`;}
const compactBooking=booking;
booking=function(){let html=compactBooking();if(state.step===2){html=html.replace(/<div class="dates"[\s\S]*?<\/div>/,fiveDates(state.bookingRange||today,state.date,'booking'));}return html;};
const compactCalendar=proCalendar;
proCalendar=function(owner=false){let html=compactCalendar(owner);return html.replace(/<div class="date-nav">[\s\S]*?<\/div>/,fiveDates(state.calendarRange||today,state.calendarDate,'calendar')).replace(/<p>No appointments/g,'<p>No appointments');};
function manualServiceChoices(id){return servicesFor(id).filter(s=>s.active!==false).map(s=>`<label class="manual-service"><input type="checkbox" name="service" value="${esc(s.id)}">${serviceIcon(s)}<span>${esc(s.name)}<small>${s.min} min · ${money(s.price)}</small></span></label>`).join('');}
manualBooking=function(){const thread=extras.conversations.find(t=>t.id===state.bookingThread),id=thread?.barber||'alex';return `${head('Add a visit.','Choose one or more services.')}<form id="manual-booking" class="panel manual-form"><fieldset class="booking-types"><legend>Booking type</legend><label><input type="radio" name="bookingType" value="walk-in">Walk-in</label><label><input type="radio" name="bookingType" value="appointment" checked>Appointment</label></fieldset><div class="form-columns"><label class="field">Client name<input name="client" value="${esc(thread?.client||'')}" ${thread?'readonly':''} required maxlength="80"></label><label class="field">Phone<input name="phone" type="tel"></label><label class="field">Store<select name="location">${Object.entries(shops).map(([key,s])=>`<option value="${key}" ${extras.location===key?'selected':''}>${s.name}</option>`).join('')}</select></label>${state.role==='Owner HQ'&&!thread?`<label class="field">Barber<select name="barber" id="manual-staff">${barbers.map(b=>`<option value="${b.id}" ${b.id===id?'selected':''}>${b.name}</option>`).join('')}</select></label>`:`<input type="hidden" name="barber" value="${id}">`}</div><fieldset><legend>Services · select one or more</legend><div id="manual-services">${manualServiceChoices(id)}</div></fieldset><p class="walk-in-note muted" hidden>Next available time today, subject to availability.</p><div class="appointment-fields form-columns"><label class="field">Date<input name="date" type="date" min="${today}" value="${days[0]}" required></label><label class="field">Time<select name="time">${times.map(t=>`<option>${t}</option>`).join('')}</select></label></div><p id="booking-error" role="alert"></p><button class="btn">Add booking</button></form>`;};
rewardCard=function(){return `<div class="reward"><div class="reward-head"><span class="logo">HAIRFLIX</span>${icon('gift')}</div><span class="reward-label">THE GOOD LOOKS CLUB</span><div class="punches">${Array.from({length:10},(_,i)=>`<span class="punch ${i<extras.punches?'filled':''}" title="Visit ${i+1}">${i<extras.punches?icon('scissors'):i===4?'50%':i===9?'FREE':i+1}</span>`).join('')}</div><h3>5th cut half off. 10th cut free.</h3><p>${extras.punches} of 10 stamps</p><button class="text-btn" data-view="rewards">View my punch card ${icon('arrow')}</button></div>`;};
rewards=function(){return head('Your fresh cut club.','One stamp per completed, approved visit.')+rewardCard();};
const privateFeedback=reviewPage;
reviewPage=function(){return privateFeedback().replace(/<label class="field">Your rating<select name="stars"[\s\S]*?<\/select><\/label>/,`<fieldset class="star-rating"><legend>Your private rating</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="stars" value="${n}" required><span aria-label="${n} stars">${'★'.repeat(n)}</span></label>`).join('')}</fieldset>`).replace('Your feedback is not posted on barber profiles or shown to your barber.','Only management sees this private feedback. Your barber and other customers cannot see it.');};
const beforePolishRender=render;
render=function(){beforePolishRender();document.body.dataset.view=state.view;document.body.dataset.step=state.step;document.querySelector('.role-entry-link')?.remove();document.querySelector('.prototype-tools')?.remove();document.querySelectorAll('[data-x="try-ticket"]').forEach(e=>e.remove());const store=document.querySelector('#shop-location-switch');if(store&&!store.closest('label')){store.insertAdjacentHTML('beforebegin','<span class="store-label">Switch store</span>');}document.querySelector('#staff-demo-select')?.closest('label')?.remove();
 if(['messages','pMessages','hMessages'].includes(state.view)){
 document.querySelector('.messenger')?.classList.toggle('chat-open',!!state.chatOpen);document.querySelector('.conversation-panel>header')?.insertAdjacentHTML('afterbegin',`<button class="icon-btn chat-back" data-polish="chat-back" aria-label="Back to conversations">${icon('back')}</button>`);
  document.querySelectorAll('.thread-row').forEach(el=>{const thread=extras.conversations.find(t=>t.id===el.dataset.id);if(thread?.kind==='general'){el.querySelector('.avatar,.matched-portraits,.account-initials')?.remove();el.insertAdjacentHTML('afterbegin',shopLogo());}});
  const t=extras.conversations.find(t=>t.id===state.threadId);if(t?.kind==='general'){document.querySelector('[data-x=general-thread]')?.remove();const header=document.querySelector('.conversation-panel>header');header?.querySelector('.avatar,.matched-portraits,.account-initials')?.remove();header?.insertAdjacentHTML('afterbegin',shopLogo());}
 }
 document.querySelectorAll('.demo-image-label').forEach(e=>e.remove());
 if(state.view==='cPayments')document.querySelector('.payment-preview')?.insertAdjacentHTML('beforeend',`<p class="policy-note">${policySummary({estimateCents:0})}</p>`);
 if(state.view==='pCalendar'||state.view==='calendar')document.querySelectorAll('main>.panel .list-item').forEach((el,i)=>{const list=(state.view==='calendar'?scopedBookings():bookings.filter(b=>b.barber===activeBarberId())).filter(b=>b.date===state.calendarDate&&b.status!=='cancelled').sort((a,b)=>minutes(a.time)-minutes(b.time));if(list[i])el.querySelector('.details')?.insertAdjacentHTML('beforeend',`<strong>${cents(list[i].estimateCents||0)}</strong>`);});
};
document.addEventListener('click',e=>{if(e.target.closest('[data-talk=select]'))state.chatOpen=true;const b=e.target.closest('[data-polish]');if(b){if(b.dataset.polish==='chat-back'){state.chatOpen=false;render();return;}const kind=b.dataset.kind,key=kind==='booking'?'bookingRange':'calendarRange';if(b.dataset.polish==='pick-date'){if(kind==='booking'){state.date=b.dataset.date;state.time='';}else state.calendarDate=b.dataset.date;}else {state[key]=addDays(state[key]||today,b.dataset.polish==='date-next'?5:-5);const selected=Array.from({length:5},(_,i)=>addDays(state[key],i)).find(d=>!dayBlocked(d,kind==='booking'?state.barber:activeBarberId()))||state[key];if(kind==='booking'){state.date=selected;state.time='';}else state.calendarDate=selected;}render();return;}
 const svc=e.target.closest('[data-service]');if(svc&&state.view==='book'&&state.step===1){e.preventDefault();e.stopImmediatePropagation();const ids=new Set(state.services||[]);ids.has(svc.dataset.service)?ids.delete(svc.dataset.service):ids.add(svc.dataset.service);state.services=[...ids];state.service=state.services[0]||'';state.time='';svc.classList.toggle('selected',ids.has(svc.dataset.service));svc.setAttribute('aria-checked',String(ids.has(svc.dataset.service)));const summary=document.querySelector('.selection-summary');if(summary){summary.querySelector('p').textContent=`${S().name} · ${S().min} min · ${money(S().price)}`;}const footer=document.querySelector('.booking-footer');if(footer){footer.querySelector('strong').textContent=money(S().price);footer.querySelector('p').textContent=`${S().name} · ${S().min} minutes`;footer.querySelector('button').disabled=!state.services.length;}}
},true);
document.addEventListener('change',e=>{if(e.target.matches('#manual-booking [name=bookingType]')){const f=e.target.form,walk=e.target.value==='walk-in';f.querySelector('.appointment-fields').hidden=walk;f.elements.date.disabled=walk;f.elements.time.disabled=walk;f.querySelector('.walk-in-note').hidden=!walk;}if(e.target.id==='manual-staff'){e.stopImmediatePropagation();document.querySelector('#manual-services').innerHTML=manualServiceChoices(e.target.value);}},true);
render();
